use vstd::prelude::*;

verus! {

fn r_(a: Vec<i8>, b: Vec<i8>) -> (res: Vec<i8>)
    ensures
        // length property
        res@.len() == a@.len() + b@.len(),
        // elements from `a` preserved
        forall|i: int|
            0 <= i < a@.len() ==> res@[i] == a@[i],
        // elements from `b` preserved at shifted indices
        forall|j: int|
            0 <= j < b@.len() ==> res@[a@.len() + j] == b@[j],
{
    let mut res: Vec<i8> = Vec::new();

    let mut i: usize = 0;
    while i < a.len()
        invariant
            i <= a.len(),
            res@ == a@.subrange(0, i as int),
            res@.len() == i as int,
        decreases a.len() - i,
    {
        res.push(a[i]);
        i = i + 1;
    }

    let a_len_usize: usize = a.len();

    let mut j: usize = 0;
    while j < b.len()
        invariant
            j <= b.len(),
            // after finishing first loop, res is all of a; now we extend with b[0..j)
            res@ == a@ + b@.subrange(0, j as int),
            res@.len() == a@.len() + j as int,
            a_len_usize == a.len(),
            a_len_usize as int == a@.len(),
        decreases b.len() - j,
    {
        res.push(b[j]);
        j = j + 1;
    }

    res
}

} // verus!

